    # the supplied colored shape, using matching offsets from that shape.
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]
    color = grid[cells[0][0]][cells[0][1]]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    out = [row[:] for row in grid]
    for r in range(h-max(a for a,b in shape)):
        for c in range(w-max(b for a,b in shape)):
            if all(grid[r+a][c+b] == 1 for a,b in shape):
                for a,b in shape:
                    out[r+a][c+b] = color
    return out
